-- TobuIsesaki (not TobuSkytree), Tobu 2026-03-14 timetable.
-- 2026-11 references only; never a physical carset, fleet identity or live observation.
CREATE TABLE IF NOT EXISTS public.published_tobu_isesaki_2611_png_references (
 edition text NOT NULL CHECK (edition='2611'),
 train_number text NOT NULL,
 train_type text NOT NULL CHECK (train_type IN ('Local','LimitedExpress')),
 scheduled_cars smallint CHECK (scheduled_cars IN (2,3)),
 illustration_model text NOT NULL,
 png_reference text NOT NULL,
 fleet_candidates text[] NOT NULL CHECK(cardinality(fleet_candidates)>0),
 official_pdf_url text NOT NULL CHECK(official_pdf_url LIKE 'https://www.tobu.co.jp/%'),
 evidence_scope text NOT NULL CHECK(evidence_scope IN ('car-count-family-only','published-express-service-model')),
 reference_only boolean NOT NULL DEFAULT true CHECK(reference_only),
 actual_vehicle_confirmed boolean NOT NULL DEFAULT false CHECK(NOT actual_vehicle_confirmed),
 PRIMARY KEY (edition,train_number),
 CHECK ((train_type='Local' AND scheduled_cars IN (2,3) AND evidence_scope='car-count-family-only')
     OR (train_type='LimitedExpress' AND scheduled_cars IS NULL AND evidence_scope='published-express-service-model'))
);
ALTER TABLE public.published_tobu_isesaki_2611_png_references ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.published_tobu_isesaki_2611_png_references FROM anon,authenticated;
COMMENT ON TABLE public.published_tobu_isesaki_2611_png_references IS
 'November 2026 TI train-number/PNG reference only. Local PNG illustrates a 2- or 3-car candidate family, not a particular trainset.';
