ON CONFLICT (edition,train_number) DO UPDATE SET
 train_type=EXCLUDED.train_type,
 scheduled_cars=EXCLUDED.scheduled_cars,
 illustration_model=EXCLUDED.illustration_model,
 png_reference=EXCLUDED.png_reference,
 fleet_candidates=EXCLUDED.fleet_candidates,
 official_pdf_url=EXCLUDED.official_pdf_url,
 evidence_scope=EXCLUDED.evidence_scope;
DO $check$
BEGIN
 IF (SELECT count(*) FROM public.published_tobu_isesaki_2611_png_references WHERE edition='2611')<>145 THEN
   RAISE EXCEPTION 'Isesaki reference count must equal 145';
 END IF;
 IF EXISTS(SELECT 1 FROM public.published_tobu_isesaki_2611_png_references
 WHERE edition='2611' AND (NOT reference_only OR actual_vehicle_confirmed)) THEN
   RAISE EXCEPTION 'Isesaki reference cannot confirm physical formations';
 END IF;
END $check$;
